from datetime import datetime

def extract_logs(logs_filepath):
    tar = tarfile.open(logs_filepath)
    tar.extractall(members=[f for f in tar.getmembers() if f.name endswith('.log')])


def process_logs(log_dir):
    for log_file in glob.glob(os.path.join(log_dir, '*.log')):
        with open(log_file, 'r') as f:
            process_log(f.read())
        os.remove(log_file)

        latest_log = max(f for f in glob.glob(log_dir + '/*.log')
                        if os.path.getmtime(f) > datetime.now().timestamp() - 3600)


def main(log_filepath):
    extract_logs(log_filepath)
    process_logs(os.path.dirname(log_filepath))


